CREATE TABLE `development` (
  `development_id` int unsigned NOT NULL AUTO_INCREMENT,
  `developer_id` int unsigned DEFAULT NULL,
  `location_id` int unsigned DEFAULT NULL,
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `latitude` decimal(9,6) DEFAULT NULL,
  `longitude` decimal(9,6) DEFAULT NULL,
  `source_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`development_id`),
  UNIQUE KEY `uq_development_developer_name` (`developer_id`,`name`),
  KEY `fk_development_location` (`location_id`),
  CONSTRAINT `fk_development_developer` FOREIGN KEY (`developer_id`) REFERENCES `developer` (`developer_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_development_location` FOREIGN KEY (`location_id`) REFERENCES `location` (`location_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_dev_latitude` CHECK (((`latitude` is null) or (`latitude` between -(90.000000) and 90.000000))),
  CONSTRAINT `ck_dev_longitude` CHECK (((`longitude` is null) or (`longitude` between -(180.000000) and 180.000000)))
) ENGINE=InnoDB AUTO_INCREMENT=6280 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
