DROP TABLE IF EXISTS `location`;
/*!40101 SET @saved_cs_client     = @@character_set_client ;
/*!50503 SET character_set_client = utf8mb4 ;
CREATE TABLE `location` (
  `location_id` int unsigned NOT NULL AUTO_INCREMENT,
  `parent_location_id` int unsigned DEFAULT NULL,
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_en` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name_ar` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `location_type` enum('governorate','city','area') COLLATE utf8mb4_unicode_ci NOT NULL,
  `latitude` decimal(9,6) DEFAULT NULL,
  `longitude` decimal(9,6) DEFAULT NULL,
  PRIMARY KEY (`location_id`),
  UNIQUE KEY `uq_location_parent_name` (`parent_location_id`,`name`),
  CONSTRAINT `fk_location_parent` FOREIGN KEY (`parent_location_id`) REFERENCES `location` (`location_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_location_latitude` CHECK (((`latitude` is null) or (`latitude` between -(90.000000) and 90.000000))),
  CONSTRAINT `ck_location_longitude` CHECK (((`longitude` is null) or (`longitude` between -(180.000000) and 180.000000)))
) ENGINE=InnoDB AUTO_INCREMENT=208 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client ;
