CREATE TABLE `property` (
  `property_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `source_listing_id` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` mediumtext COLLATE utf8mb4_unicode_ci,
  `development_id` int unsigned DEFAULT NULL,
  `location_id` int unsigned NOT NULL,
  `property_type_id` int unsigned NOT NULL,
  `payment_method_id` int unsigned DEFAULT NULL,
  `area_sqm` decimal(10,2) NOT NULL,
  `bedrooms` tinyint unsigned DEFAULT NULL,
  `bathrooms` tinyint unsigned DEFAULT NULL,
  `price` decimal(15,2) NOT NULL,
  `market_price` decimal(15,2) DEFAULT NULL,
  `down_payment` decimal(15,2) DEFAULT NULL,
  `installment_amount` decimal(15,2) DEFAULT NULL,
  `installment_frequency` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `installment_years` decimal(4,1) DEFAULT NULL,
  `remaining_balance` decimal(15,2) DEFAULT NULL,
  `gain_over_market_value` decimal(15,2) DEFAULT NULL,
  `gain_percentage` decimal(7,2) DEFAULT NULL,
  `discount_over_market_price` decimal(15,2) DEFAULT NULL,
  `contract_year` smallint unsigned DEFAULT NULL,
  `delivery_year` smallint unsigned DEFAULT NULL,
  `currency` char(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'EGP',
  `scraped_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`property_id`),
  UNIQUE KEY `uq_property_source_listing_id` (`source_listing_id`),
  KEY `fk_property_type` (`property_type_id`),
  KEY `fk_property_payment_method` (`payment_method_id`),
  KEY `idx_property_loc_type` (`location_id`,`property_type_id`),
  KEY `idx_property_dev_type` (`development_id`,`property_type_id`),
  KEY `idx_property_price` (`price`),
  KEY `idx_property_contract_year` (`contract_year`),
  CONSTRAINT `fk_property_development` FOREIGN KEY (`development_id`) REFERENCES `development` (`development_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_property_location` FOREIGN KEY (`location_id`) REFERENCES `location` (`location_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_property_payment_method` FOREIGN KEY (`payment_method_id`) REFERENCES `payment_method` (`payment_method_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_property_type` FOREIGN KEY (`property_type_id`) REFERENCES `property_type` (`property_type_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_property_area` CHECK ((`area_sqm` > 0)),
  CONSTRAINT `ck_property_contract_year` CHECK (((`contract_year` is null) or (`contract_year` between 1990 and 2030))),
  CONSTRAINT `ck_property_down_payment` CHECK (((`down_payment` is null) or ((`down_payment` >= 0) and (`down_payment` <= `price`)))),
  CONSTRAINT `ck_property_installment` CHECK (((`installment_amount` is null) or (`installment_amount` >= 0))),
  CONSTRAINT `ck_property_market_price` CHECK (((`market_price` is null) or (`market_price` >= 0))),
  CONSTRAINT `ck_property_price` CHECK ((`price` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=9629 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
